namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string CategorySlug { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace RecipeHub.Models;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Category is required.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Ingredients are required.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Steps are required.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Bruschetta", Category = "Appetizers", CategorySlug = "appetizers", Ingredients = "Baguette, tomatoes, basil, garlic, olive oil", Steps = "1. Toast bread slices\n2. Mix diced tomatoes with garlic and basil\n3. Top bread with tomato mixture\n4. Drizzle with olive oil", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Stuffed Mushrooms", Category = "Appetizers", CategorySlug = "appetizers", Ingredients = "Mushrooms, cream cheese, garlic, breadcrumbs, parsley", Steps = "1. Remove mushroom stems\n2. Mix cream cheese, garlic, and breadcrumbs\n3. Fill mushroom caps\n4. Bake at 375°F for 20 minutes", AverageRating = 4.2, RatingCount = 8 },
        new Recipe { Id = 3, Title = "Spaghetti Carbonara", Category = "Main Courses", CategorySlug = "main-courses", Ingredients = "Spaghetti, eggs, pancetta, parmesan, black pepper", Steps = "1. Cook spaghetti al dente\n2. Fry pancetta until crisp\n3. Whisk eggs with parmesan\n4. Toss hot pasta with pancetta, then egg mixture\n5. Season with black pepper", AverageRating = 4.8, RatingCount = 25 },
        new Recipe { Id = 4, Title = "Chicken Tikka Masala", Category = "Main Courses", CategorySlug = "main-courses", Ingredients = "Chicken, yogurt, tomato sauce, cream, garam masala, cumin", Steps = "1. Marinate chicken in yogurt and spices\n2. Grill or bake chicken\n3. Simmer tomato sauce with cream and spices\n4. Add chicken to sauce\n5. Serve with rice or naan", AverageRating = 4.7, RatingCount = 18 },
        new Recipe { Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", CategorySlug = "desserts", Ingredients = "Dark chocolate, butter, eggs, sugar, flour", Steps = "1. Melt chocolate and butter together\n2. Whisk eggs and sugar until fluffy\n3. Fold in chocolate mixture and flour\n4. Pour into greased ramekins\n5. Bake at 425°F for 12 minutes", AverageRating = 4.9, RatingCount = 30 },
        new Recipe { Id = 6, Title = "Tiramisu", Category = "Desserts", CategorySlug = "desserts", Ingredients = "Ladyfingers, espresso, mascarpone, eggs, sugar, cocoa", Steps = "1. Mix egg yolks with sugar\n2. Fold in mascarpone\n3. Dip ladyfingers in espresso\n4. Layer ladyfingers and cream\n5. Refrigerate overnight\n6. Dust with cocoa", AverageRating = 4.6, RatingCount = 15 },
    };

    public List<Recipe> GetByCategory(string categorySlug)
    {
        return _recipes.Where(r => r.CategorySlug == categorySlug).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().ToList();
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        var slug = submission.Category.ToLower().Replace(" ", "-");
        _recipes.Add(new Recipe
        {
            Id = _recipes.Max(r => r.Id) + 1,
            Title = submission.Title,
            Category = submission.Category,
            CategorySlug = slug,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = (totalStars + stars) / recipe.RatingCount;
        }
    }
}

